from common import *
import numpy as np

def difference(a,b):
    return {'exact':bool(np.array_equal(a,b,equal_nan=True)), 'n':int(a.size),'changed':int(np.count_nonzero(a!=b)),'max_abs':float(np.nanmax(np.abs(a-b))),'mean_abs':float(np.nanmean(np.abs(a-b)))}

def compare(a,b):
    da=read(BASE/'docs'/f'{PREFIX}-{a}.json');db=read(BASE/'docs'/f'{PREFIX}-{b}.json')
    ca=np.array([r['objective'] for r in da['rounds']]);cb=np.array([r['objective'] for r in db['rounds']]);n=min(len(ca),len(cb))
    changed=np.flatnonzero(ca[:n]!=cb[:n]); trees=[i+1 for i,(x,y) in enumerate(zip(da['rounds'],db['rounds'])) if x['tree_sha256']!=y['tree_sha256']]
    pa=np.load(TMP/f'{a}-valid-pred.npy');pb=np.load(TMP/f'{b}-valid-pred.npy')
    return {'a':a,'b':b,'round_counts':[len(ca),len(cb)],'best_iterations':[da['early_stopping'][0]['best_iteration'],db['early_stopping'][0]['best_iteration']], 'objective_shared':difference(ca[:n],cb[:n]),'first_changed_objective_round':int(changed[0]+1) if len(changed) else None,'first_changed_tree_round':trees[0] if trees else None,'changed_tree_rounds':trees, 'valid_prediction':difference(pa,pb),'booster_file_exact':da['selected_booster']['sha256']==db['selected_booster']['sha256']}

if __name__=='__main__':
    register_adapter(__file__)
    mode=sys.argv[1] if len(sys.argv)>1 else 'original'
    jobs=[f'{label}-s3000-r{r}-{mode}' for r in [1,2] for label in ['old','new']]
    pairs=[(jobs[0],jobs[2]),(jobs[1],jobs[3]),(jobs[0],jobs[1]),(jobs[2],jobs[3])]
    result={'mode':mode,'comparisons':[compare(a,b) for a,b in pairs],'scope':'Two separate-process repeats per label at seed3000. Does not establish universal stability across all seeds/hardware or original historical v2 reproducibility.'}
    for label in ['old','new']:
        d=read(BASE/'docs'/f'{PREFIX}-{label}-s3000-r1-{mode}.json')
        if label=='new':
            orig=read(BASE/'docs/training-h20-s3000.json')['curves'];cur=d['rounds'];n=min(len(orig),len(cur));a=np.array([r['official'] for r in orig[:n]]);b=np.array([r['objective'] for r in cur[:n]])
            result['new_vs_archived_objective']={'rounds':[len(orig),len(cur)],**difference(a,b)}
        else:
            orig=next(x for x in read(BASE/'docs/H20-observed-label-effect.json')['seeds'] if x['seed']==3000)['old_p50']
            result['old_vs_archived_summary']={'historical':orig,'replayed':d['early_stopping'][0],'full_historical_curve_available':False}
    write(BASE/'docs'/f'{PREFIX}-{mode}-comparison.json',result)
    print(json.dumps(result,ensure_ascii=False,indent=2))
